/// Execute a command using bash
async fn execute_command(
410→    command: &str,
    working_dir: &str,
    max_output: usize,
    use_shell: bool,
) -> Result<(String, String, i32), String> {
    let mut process = if use_shell {
        let mut cmd = Command::new("bash");
        cmd.arg("-c").arg(command);
        cmd
    } else {
420→        let words = shell_words::split(command).map_err(|e| e.to_string())?;
        let executable = words.first().ok_or_else(|| "Empty command".to_string())?;
        let mut cmd = Command::new(executable);
        cmd.args(&words[1..]);
        cmd
    };
    let mut child = process
        .current_dir(working_dir)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
430→        .stdin(Stdio::null())
        .spawn()
        .map_err(|e| format!("Failed to spawn command: {}", e))?;

    let mut stdout = String::new();
    let mut stderr = String::new();

    if let Some(mut stdout_pipe) = child.stdout.take() {
        stdout_pipe
            .read_to_string(&mut stdout)
440→            .await
            .map_err(|e| format!("Failed to read stdout: {}", e))?;
    }

    if let Some(mut stderr_pipe) = child.stderr.take() {
        stderr_pipe
            .read_to_string(&mut stderr)
            .await
            .map_err(|e| format!("Failed to read stderr: {}", e))?;
    }
450→
    let status = child
        .wait()
        .await
        .map_err(|e| format!("Failed to wait for command: {}", e))?;

    let exit_code = status.code().unwrap_or(-1);

    // Truncate if needed
    if stdout.len() > max_output {
460→        stdout.truncate(max_output);
        stdout.push_str("\n... (output truncated)");
    }
    if stderr.len() > max_output {
        stderr.truncate(max_output);
        stderr.push_str("\n... (output truncated)");
    }

    Ok((stdout, stderr, exit_code))
}
